steps.script:
$l=@(Get-Content 'C:\TTiTTulares\ttittulares-mobile-trigger.log' -Tail 350)
$id='tt-placeholderfix-1794482726176'
$o=@{state='pending';seen=@($l|Where-Object{$_ -match $id}).Count;last_error='none';draft_length=0;placeholder_match=$false}
if(@($l|Where-Object{$_ -match ('LAUNCH CONFIRMED.*'+$id)}).Count){$o.state='confirmed'}
if(@($l|Where-Object{$_ -match ('LAUNCH FAILED.*'+$id)}).Count){$o.state='failed'}
$g=[string]($l|Where-Object{$_ -match 'NEW_CHAT_NOT_BLANK'}|Select-Object -Last 1)
if($g -match 'editorLength[^0-9]*([0-9]+)'){$o.draft_length=[int]$Matches[1]}
if($g -match 'placeholderMatch[^a-z]*(true|false)'){$o.placeholder_match=($Matches[1] -eq 'true')}
if(@($l|Where-Object{$_ -match 'NEW_CHAT_CONTROL_UNAVAILABLE'}).Count){$o.last_error='control'}
elseif(@($l|Where-Object{$_ -match 'Fresh tab has draft'}).Count){$o.last_error='draft'}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
